# <glob, relative to the nvim config dir>  <areas...>   (suite.sh --changed)
# A changed file matching no line runs every area. startup and smoke always run under --changed.
init.lua                          startup tools
lazy-lock.json                    startup installer lsp format lint treesitter git completion which-key ui editing tools
lua/core/lazy.lua                 startup installer
lua/features/init.lua             startup installer
lua/lsp/buffer.lua                lsp keys which-key
lua/lsp/init.lua                  lsp tools
lua/lang/*                        lsp tools format lint treesitter editing
after/ftplugin/*                  lsp format editing
lua/tools/*                       tools lsp format lint
lua/tools/ux.lua                  ui
lua/ui/*                          ui tools lint
lua/format/*                      format keys
lua/linting/*                     lint keys ui
lua/features/treesitter.lua       treesitter keys which-key
lua/features/git.lua              git keys which-key
lua/features/completion.lua       completion
lua/keys/*                        keys which-key lsp git lint format treesitter
lua/textobjects/*                 treesitter keys which-key
lua/features/editing.lua          editing keys which-key
lua/features/diagnostics.lua      ui lsp
lua/ui/snacks.lua                 ui keys git
lua/features/search.lua           keys editing
lua/plugins/extras.lua            ui editing keys
lua/plugins/dap.lua               keys
lua/config/keymaps.lua            keys which-key
lua/config/options.lua            editing ui
lua/config/autocmds.lua           editing ui
lua/ui/messages/*                ui
lua/config/helpers.lua            keys lsp
lua/config/utils.lua              keys lsp
.luarc.json                       smoke
.luacheckrc                       smoke
stylua.toml                       smoke
.editorconfig                     smoke
